    base='build/literature-review/spyrrow-runtime/';get=lambda n:json.loads(files[base+n]);original=get('communication-original-1/COMPLETED.json');assert original['status']=='PASS_EXACT_SPYRROW_ORIGINAL_COMPONENT_REFERENCES_ONLY' and original['cases']==21 and original['complete_numeric_cells']==331480 and original['hash_cases']==5008 and original['set_groups']==9 and original['largest_set_input']==85000 and original['distance_cases']==2006 and original['shared_runtime_unchanged'] and original['overlay_unchanged'] and original['source_inputs_unchanged'] and not original['owned_root_alive'];details=get('communication-original-1/original/COMPLETED.json');assert details['hash_seed']==0 and details['hash_algorithm']=='siphash13' and not details['full_package_imported'] and not details['functions_or_code_objects_patched'] and not details['pickle_file_loaded'];assert {r['id']:r['type'] for r in details['original_errors']}=={'no-pairs':'IndexError','duplicate-cell-index':'AttributeError','colon-gene-key':'KeyError'};cn=details['cn_module_import_error'];assert cn['type']=='NameError' and 'nam' in cn['message'] and not cn['root_package_initialization_executed'] and cn['component_namespace_parents'] and not cn['pickle_file_loaded']
