    for run in native['runs']:assert run['exit_code']==0 and run['cases']==21 and run['comparisons']==dict(numeric=333478,exact=100040) and len(run['expected_rejections'])==14 and run['operations']==297416
    adversarial=get('communication-comparison-adversarial-2/COMPLETED.json');assert adversarial['status']=='PASS_NINE_SPYRROW_COMPARISON_CORRUPTION_CONTROLS_ONLY' and len(adversarial['checks'])==9;failed=get('communication-comparison-adversarial-1/FAILED.json');assert failed['status']=='FAIL2_COMPARISON_TEST_RELATIVE_PATH_ONLY';setup=get('component-reference-setup-1/COMPLETED.json');assert setup['status']=='PASS_SPYRROW_ORIGINAL_BASIC_COMPONENT_REFERENCE_ONLY' and setup['shared_runtime_unchanged'] and not setup['full_spyrrow_package_imported'] and not setup['pickle_file_loaded'];denied=get('component-setup-denied-control-1/COMPLETED.json');assert denied['exit_code']==3 and not denied['software_overlay_created'];build=get('communication-build-1/COMPLETED.json');assert build['artifact']==p['artifact'] and build['unchanged_parent_entries']==21022 and len(build['added_entries'])==46
    finding=get('python-hash-seed-launch-audit-1/COMPLETED.json');assert finding['status']=='CONFIRMED_OPEN_CELLPHONEDB_PYTHON_HASH_SEED_OPTION_DEFECT' and not finding['source_or_runtime_changed'] and not finding['scientific_outputs_relabelled'];assert len(finding['records'])==6 and all(r['exit_code']==0 for r in finding['records']);assert [r['observed']['ignore_environment'] for r in finding['records']]==[1,1,0,0,0,0];assert finding['records'][2]['observed']['hash']==finding['records'][3]['observed']['hash'] and finding['records'][4]['observed']['hash']==finding['records'][5]['observed']['hash'];draft=json.loads((ROOT/'tools/literature/spyrrow-use-review-expansion.json').read_bytes());assert not draft['applied'] and not draft['implementation_credit'] and draft['primary_paragraph']==27 and draft['review']['supporting_evidence'][0]['paragraph_index']==29;assert pin(ROOT/'build/cli/omicsmatic-0.3.7.jar')==p['canonical_executable_unchanged'];artifact=ROOT/p['artifact']['path']
    if artifact.exists():assert pin(artifact)=={k:p['artifact'][k] for k in ['bytes','sha256']}
